#!/usr/bin/env bash
# uv（pyproject.toml と uv.lock）で依存を管理しているかを、git 上のファイルだけを見て検査する
set -euo pipefail

# 対象 repo 由来のパスをそのまま埋めるとワークフローコマンドを偽装できるためエスケープする
escape() { local value=${1//%/%25}; value=${value//$'\r'/%0D}; printf '%s' "${value//$'\n'/%0A}"; }
escape_property() { local value; value=$(escape "$1"); value=${value//:/%3A}; printf '%s' "${value//,/%2C}"; }
status=0
# requirements 系は依存管理として使われているものだけを対象にする
# （pyproject.toml がある repo ではその隣にあるもの、無い repo は Python コードがあるときだけ）
manifests=$(git ls-files -- ':(glob)**/pyproject.toml')
sources=$(git ls-files -- ':(glob)**/*.py' ':(glob)**/*.pyi')
# プロセス置換では git の失敗が伝わらないため、いったんファイルに受ける。
# 対象を増やすときは style.yml の paths-filter の python にも追加する（フィルタから漏れると起動しない）
files=$(mktemp)
git ls-files -z -- ':(glob)**/*requirements*.txt' ':(glob)**/requirements/*.txt' ':(glob)**/setup.py' ':(glob)**/setup.cfg' ':(glob)**/Pipfile' ':(glob)**/Pipfile.lock' ':(glob)**/poetry.lock' ':(glob)**/pdm.lock' > "${files}"
while IFS= read -r -d '' file; do
  dir=$(dirname "${file}")
  case "${file}" in
    *requirements/*.txt|*requirements*.txt)
      # requirements/ に分けている場合は、その親を宣言の置き場所とみなす
      case "${file}" in *requirements/*.txt) dir=$(dirname "${dir}") ;; esac
      if [ -n "${manifests}" ]; then
        if [ ! -e "${dir}/pyproject.toml" ]; then continue; fi
      elif [ -z "${sources}" ]; then
        continue
      fi
      # uv export で書き出したものは配布用の成果物として許可する
      IFS= read -r first < "${file}" || true
      case "${first}" in *'autogenerated by uv'*) continue ;; esac ;;
    # 依存を宣言しない setup.py / setup.cfg は、ビルド定義（C 拡張等）や他ツールの設定として許可する
    setup.py|setup.cfg|*/setup.py|*/setup.cfg)
      if ! grep -qE '(install|setup)_requires' "${file}"; then continue; fi ;;
  esac
  echo "::error file=$(escape_property "${file}")::$(escape "${file}") ではなく pyproject.toml と uv.lock で依存を管理してください（https://docs.astral.sh/uv/guides/migration/pip-to-project/）"
  status=1
done < "${files}"
# 自分の uv.lock を持つか、祖先の lock に記録されている（= workspace の member である）ことを確認する。
# lock が最新かは依存関係の導入時に uv が判定する
jq -j '.[] | .path, "\u0000", .project, "\u0000", .rel, "\u0000"' <<< "${PYPROJECTS}" > "${files}"
while IFS= read -r -d '' path && IFS= read -r -d '' project && IFS= read -r -d '' rel; do
  if [ -z "${project}" ]; then
    echo "::error file=$(escape_property "${path}")::uv.lock がありません。uv lock を実行して uv.lock をコミットしてください（https://docs.astral.sh/uv/concepts/projects/layout/#the-lockfile）"
    status=1
  elif [ "${rel}" != . ] && ! grep -qsF -e "editable = \"${rel}\"" -e "virtual = \"${rel}\"" -e "directory = \"${rel}\"" "${project}/uv.lock"; then
    echo "::error file=$(escape_property "${path}")::uv.lock に含まれていません。uv lock を実行して uv.lock をコミットするか、workspace の members に追加してください（https://docs.astral.sh/uv/concepts/projects/workspaces/）"
    status=1
  fi
done < "${files}"
# どの uv.lock にも属さない import-linter の設定は、検査に使う環境を作れないため誰も検査できない
jq -j '.[] | select(.project == "") | .path, "\u0000"' <<< "${IMPORTLINTERS}" > "${files}"
while IFS= read -r -d '' path; do
  echo "::error file=$(escape_property "${path}")::import-linter の設定がどの uv.lock の配下にもないため検査できません。pyproject.toml と uv.lock で依存を管理してください（https://docs.astral.sh/uv/guides/migration/pip-to-project/）"
  status=1
done < "${files}"
exit "${status}"
